// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"O que cabe ao professor","html":"<p>Em toda turma há alunos que aprendem, se concentram e se relacionam de formas diferentes. Parte deles tem uma condição do neurodesenvolvimento, como o TDAH, o autismo ou a dislexia. Outros têm altas habilidades e aprendem sozinhos mais rápido do que a turma.</p><p>O professor <b>não faz diagnóstico</b>. Ele observa, registra, adapta a aula e comunica à coordenação, que conversa com a família e aciona a rede de saúde. O diagnóstico é feito por profissionais de saúde.</p><h3>Ao final, você será capaz de</h3><ul><li>Reconhecer sinais que pedem observação mais atenta.</li><li>Registrar o que observa de forma útil para a família e para a saúde.</li><li>Adaptar a aula sem esperar um laudo.</li><li>Conversar com os responsáveis sem rotular.</li><li>Conhecer os direitos do aluno.</li></ul><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Observar</b><small>por algumas semanas, em situações diferentes</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Registrar</b><small>fatos, frequência e contexto</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Adaptar</b><small>mudar o ambiente e a tarefa</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Comunicar</b><small>coordenação e família</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Encaminhar</b><small>a escola aciona a saúde</small></div></div><figcaption>Figura. O caminho do professor diante de um aluno que aprende de forma diferente.</figcaption></figure><div class=\"nota alerta\"><b>Cuidado com o rótulo</b><br/>Agitação, desatenção ou isolamento têm muitas causas: sono, fome, problemas em casa, dificuldade de visão ou de audição, aula pouco adequada. Dizer que um aluno \"tem TDAH\" ou \"é autista\" sem avaliação pode prejudicá-lo.</div>"},{"id":"c2","titulo":"Os direitos do aluno","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Norma</th><th>O que garante</th></tr></thead><tbody><tr><td>Lei nº 14.254/2021</td><td>Acompanhamento integral para alunos com dislexia, TDAH ou outro transtorno de aprendizagem, com identificação precoce, encaminhamento para diagnóstico e apoio na escola e na saúde.</td></tr><tr><td>Lei nº 12.764/2012</td><td>Direitos da pessoa com transtorno do espectro autista, inclusive à educação e, quando comprovada a necessidade, a acompanhante especializado.</td></tr><tr><td>Lei nº 13.146/2015</td><td>Lei Brasileira de Inclusão: sistema educacional inclusivo e adaptações razoáveis. É proibido recusar matrícula.</td></tr><tr><td>Lei de Diretrizes e Bases, arts. 58 a 60</td><td>Atendimento educacional especializado a alunos com deficiência, transtornos globais do desenvolvimento e altas habilidades ou superdotação.</td></tr></tbody></table></div><div class=\"nota\"><b>Apoio não depende de laudo</b><br/>As adaptações em sala podem e devem começar assim que o professor percebe a necessidade. O laudo orienta o atendimento, mas a falta dele não justifica deixar o aluno sem apoio.</div>"},{"id":"c3","titulo":"Sinais de TDAH","html":"<p>O transtorno do déficit de atenção com hiperatividade envolve desatenção, hiperatividade e impulsividade em grau que atrapalha a vida do aluno. Os sinais aparecem em mais de um ambiente e persistem por meses.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>O que pode aparecer em sala</th></tr></thead><tbody><tr><td>Desatenção</td><td>Perde o fio da explicação. Não termina as tarefas. Erra por descuido. Perde material. Parece não ouvir. Evita atividades longas.</td></tr><tr><td>Hiperatividade</td><td>Levanta com frequência. Mexe mãos e pés. Fala muito. Tem dificuldade em brincar ou trabalhar em silêncio.</td></tr><tr><td>Impulsividade</td><td>Responde antes do fim da pergunta. Interrompe. Tem dificuldade de esperar a vez. Age sem medir a consequência.</td></tr></tbody></table></div><h3>O que ajuda em sala</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Estratégia</th><th>Como fazer</th></tr></thead><tbody><tr><td>Lugar</td><td>Sentar perto do professor, longe de janela e de porta.</td></tr><tr><td>Instruções</td><td>Uma de cada vez, curtas, olhando para o aluno. Pedir que repita.</td></tr><tr><td>Tarefas</td><td>Dividir em partes pequenas, com pausa entre elas.</td></tr><tr><td>Movimento</td><td>Dar funções que permitam levantar: distribuir material, apagar o quadro.</td></tr><tr><td>Rotina</td><td>Deixar a sequência da aula visível no quadro.</td></tr><tr><td>Retorno</td><td>Elogiar logo o que deu certo. Corrigir em particular.</td></tr><tr><td>Tempo</td><td>Dar mais tempo ou reduzir a quantidade, mantendo o objetivo.</td></tr></tbody></table></div><div class=\"nota\"><b>Nem todo aluno com TDAH é agitado</b><br/>Há alunos, com frequência meninas, em que predomina a desatenção. Eles são quietos, parecem distraídos e passam despercebidos.</div>"},{"id":"c4","titulo":"Sinais do espectro autista","html":"<p>O transtorno do espectro autista envolve diferenças na comunicação e na interação social e padrões restritos ou repetitivos de comportamento e de interesses. A intensidade varia muito de uma pessoa para outra.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>O que pode aparecer em sala</th></tr></thead><tbody><tr><td>Comunicação</td><td>Pouco contato visual. Fala literal, com dificuldade de entender ironia e duplo sentido. Fala muito de um mesmo assunto.</td></tr><tr><td>Interação</td><td>Prefere ficar sozinho. Tem dificuldade de entrar em brincadeiras e de entender regras sociais não ditas.</td></tr><tr><td>Rotina</td><td>Incômodo forte com mudanças. Necessidade de fazer as coisas sempre do mesmo modo.</td></tr><tr><td>Sentidos</td><td>Incômodo com barulho, luz, cheiros ou toque. Pode tapar os ouvidos ou se afastar.</td></tr><tr><td>Interesses</td><td>Interesse intenso e profundo por um tema.</td></tr><tr><td>Movimentos</td><td>Movimentos repetitivos, que ajudam o aluno a se regular.</td></tr></tbody></table></div><h3>O que ajuda em sala</h3><ul><li>Avisar com antecedência as mudanças de rotina.</li><li>Usar apoio visual: sequência da aula, passo a passo da tarefa.</li><li>Dar instruções claras e literais.</li><li>Combinar um lugar tranquilo para o aluno se recompor.</li><li>Usar o interesse dele como porta para o conteúdo.</li><li>Preparar a turma para a convivência, sem expor o colega.</li><li>Não forçar contato visual nem contato físico.</li></ul>"},{"id":"c5","titulo":"Dislexia e outros transtornos de aprendizagem","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Condição</th><th>Sinais em sala</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Dislexia (leitura)</td><td>Leitura lenta e com esforço. Troca, omissão ou inversão de letras que persiste. Dificuldade de rimar. Compreende bem o que ouve.</td><td>Ler os enunciados em voz alta. Dar mais tempo. Avaliar também de forma oral. Usar letra maior e texto bem espaçado.</td></tr><tr><td>Disgrafia (escrita)</td><td>Letra de difícil leitura, traçado lento, dor ao escrever.</td><td>Reduzir a cópia. Aceitar respostas mais curtas. Permitir outros meios de registro.</td></tr><tr><td>Discalculia (matemática)</td><td>Dificuldade persistente com quantidades, contagem e fatos básicos.</td><td>Usar material concreto. Permitir tabelas de apoio. Dar um passo de cada vez.</td></tr></tbody></table></div><div class=\"nota\"><b>O reforço escolar ajuda a perceber</b><br/>Quando um aluno avança em quase todas as habilidades e fica parado sempre nas que dependem de leitura, de escrita ou de cálculo básico, mesmo voltando aos pré-requisitos, vale levar o caso à coordenação.</div>"},{"id":"c6","titulo":"Altas habilidades e alunos que aprendem sozinhos","html":"<p>Alunos com altas habilidades ou superdotação têm desempenho ou potencial elevado em uma ou mais áreas: intelectual, acadêmica, criativa, artística, de liderança ou psicomotora. Muitos aprendem por conta própria e chegam à aula já sabendo o conteúdo.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O que pode aparecer</th><th>Como costuma ser interpretado por engano</th></tr></thead><tbody><tr><td>Termina rápido e fica sem o que fazer.</td><td>Desinteresse ou indisciplina.</td></tr><tr><td>Faz muitas perguntas e questiona regras.</td><td>Falta de respeito.</td></tr><tr><td>Aprende sozinho, por livros e vídeos.</td><td>Não precisa da escola.</td></tr><tr><td>Tem vocabulário e raciocínio acima da idade.</td><td>Quer aparecer.</td></tr><tr><td>Sente tédio com repetição e pode ir mal nas tarefas simples.</td><td>Preguiça.</td></tr><tr><td>É muito sensível e autocrítico.</td><td>Imaturidade.</td></tr></tbody></table></div><h3>O que ajuda em sala</h3><ul><li>Oferecer desafios mais complexos, em vez de mais do mesmo.</li><li>Permitir que aprofunde um tema de interesse e apresente à turma.</li><li>Convidá-lo a ajudar colegas, sem transformá-lo em monitor permanente.</li><li>No reforço escolar, deixar que avance para habilidades de anos seguintes.</li><li>Comunicar à coordenação, para avaliar o atendimento educacional especializado.</li></ul><div class=\"nota\"><b>Dupla condição</b><br/>Um aluno pode ter altas habilidades e, ao mesmo tempo, TDAH, autismo ou dislexia. Nesses casos, uma condição pode esconder a outra.</div>"},{"id":"c7","titulo":"Como observar e registrar","html":"<p>Um bom registro descreve fatos, sem interpretação. Ele é a principal contribuição da escola para a família e para a saúde.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Registre</th></tr></thead><tbody><tr><td>\"É desatento.\"</td><td>\"Em cinco aulas de Matemática, começou a atividade e parou antes da metade em quatro.\"</td></tr><tr><td>\"Não se socializa.\"</td><td>\"No recreio, ficou sozinho nos dez dias observados. Aceitou brincar quando um colega o chamou.\"</td></tr><tr><td>\"É muito inteligente.\"</td><td>\"Resolveu sem ajuda problemas do ano seguinte e explicou o raciocínio à turma.\"</td></tr></tbody></table></div><ul class=\"chk\"><li><span></span>Observei em dias, horários e atividades diferentes.</li><li><span></span>Anotei o que aconteceu antes e depois do comportamento.</li><li><span></span>Anotei o que já tentei e o que funcionou.</li><li><span></span>Perguntei a outros professores se observam o mesmo.</li><li><span></span>Levei o registro à coordenação.</li></ul>"},{"id":"c8","titulo":"A conversa com os responsáveis","html":"<ol class=\"passos\"><li>A conversa é feita com a coordenação, em local reservado.</li><li>Comece pelo que o aluno faz bem.</li><li>Descreva o que a escola observou, com exemplos.</li><li>Pergunte se a família percebe algo parecido em casa.</li><li>Explique o que a escola já está fazendo em sala.</li><li>Sugira a avaliação por profissional de saúde, sem nomear um diagnóstico.</li><li>Combine um retorno.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Acho que ele tem TDAH.\"</td><td>\"Percebemos que ele tem dificuldade de manter a atenção em tarefas longas. Vale conversar com o pediatra.\"</td></tr><tr><td>\"Ela precisa de laudo.\"</td><td>\"Uma avaliação pode nos ajudar a entender como apoiá-la melhor.\"</td></tr><tr><td>\"Ele atrapalha a turma.\"</td><td>\"Ele aprende melhor quando pode se movimentar. Estamos adaptando as atividades.\"</td></tr></tbody></table></div>"},{"id":"c9","titulo":"Uma sala que funciona para todos","html":"<p>Muitas estratégias pensadas para um aluno melhoram a aula para a turma inteira.</p><figure><div class=\"matriz\"><div class=\"ey\">Benefício para a turma</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Rotina visível no quadro</b><small>Pouco esforço, muito benefício. Comece por aqui.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Atividades em estações</b><small>Mais esforço, muito benefício. Planeje com colegas.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Instruções curtas e uma por vez</b><small>Pouco esforço, benefício imediato.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Material adaptado individual</b><small>Mais esforço, benefício para poucos. Faça com apoio do atendimento especializado.</small></div></div><div class=\"ex\">Esforço para aplicar</div></div><figcaption>Figura. Por onde começar.</figcaption></figure><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o aluno que não parava</div><p><b>Situação.</b> Um aluno do 4º ano levanta o tempo todo, não termina as tarefas e é chamado à atenção várias vezes por dia.</p><p><b>O que fazer.</b></p><ol><li>Observe por duas semanas e registre quando a agitação é maior.</li><li>Mude o lugar dele e divida as tarefas em partes.</li><li>Dê a ele funções com movimento.</li><li>Leve o registro à coordenação, que conversa com os responsáveis.</li><li>Combine com os demais professores as mesmas estratégias.</li></ol><p><b>Resultado esperado.</b> O aluno passa a concluir mais tarefas, as chamadas de atenção diminuem, e a família busca a avaliação.</p></div>"},{"id":"c10","titulo":"Palavras que ajudam e palavras que atrapalham","html":"<p>Neurodiversidade é a ideia de que os cérebros humanos funcionam de formas variadas, assim como variam a altura e o temperamento. Chama-se neurodivergente a pessoa cujo modo de perceber, aprender e se relacionar foge do mais comum, como ocorre no autismo, no TDAH e na dislexia.</p><p>A palavra que o professor usa molda o que a turma pensa do colega e o que o aluno pensa de si.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Termo</th><th>O que significa</th></tr></thead><tbody><tr><td>Neurodivergente</td><td>Pessoa com desenvolvimento neurológico diferente do mais comum.</td></tr><tr><td>Transtorno do neurodesenvolvimento</td><td>Condição que começa na infância e afeta atenção, linguagem, aprendizagem, interação ou movimento. Inclui TDAH, autismo e transtornos de aprendizagem.</td></tr><tr><td>Transtorno específico da aprendizagem</td><td>Dificuldade persistente em leitura, escrita ou matemática, sem relação com falta de ensino ou de inteligência.</td></tr><tr><td>Deficiência</td><td>Impedimento de longo prazo que, diante de barreiras, limita a participação. A lei brasileira considera a pessoa autista como pessoa com deficiência.</td></tr><tr><td>Altas habilidades ou superdotação</td><td>Potencial elevado em uma ou mais áreas, com criatividade e envolvimento.</td></tr><tr><td>Laudo</td><td>Documento de profissional de saúde com a avaliação e o diagnóstico.</td></tr><tr><td>Barreira</td><td>O que impede a participação: uma escada, um texto sem adaptação, uma atitude.</td></tr><tr><td>Adaptação razoável</td><td>Ajuste necessário para que o aluno participe em igualdade com os demais.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Aluno-problema\", \"aluno de inclusão\", \"o laudado\"</td><td>O nome do aluno.</td></tr><tr><td>\"Ele é TDAH.\"</td><td>\"Ele tem TDAH.\"</td></tr><tr><td>\"Portador de autismo.\"</td><td>\"Aluno autista\" ou \"aluno com autismo\", como a família preferir.</td></tr><tr><td>\"Ele é preguiçoso.\"</td><td>\"Ele ainda não consegue começar sozinho.\"</td></tr><tr><td>\"Normal.\"</td><td>\"Sem deficiência\" ou \"com desenvolvimento típico\".</td></tr><tr><td>\"Sofre de dislexia.\"</td><td>\"Tem dislexia.\"</td></tr><tr><td>\"Apesar da deficiência, ele consegue.\"</td><td>\"Ele consegue.\"</td></tr></tbody></table></div>"},{"id":"c11","titulo":"Defasagem, dificuldade ou transtorno","html":"<p>Nem todo aluno que não aprende tem um transtorno. Confundir as três situações leva a dois erros: mandar para o médico quem só precisa de ensino, e insistir no mesmo ensino com quem precisa de avaliação.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th></th><th>Defasagem</th><th>Dificuldade passageira</th><th>Transtorno</th></tr></thead><tbody><tr><td>O que é</td><td>O aluno não aprendeu conteúdos de anos anteriores.</td><td>Queda ligada a um momento: luto, mudança, doença, conflito.</td><td>Condição do neurodesenvolvimento, persistente.</td></tr><tr><td>Como aparece</td><td>Erra o que depende de pré-requisitos. Avança quando o conteúdo é retomado.</td><td>Antes aprendia bem. A queda tem data.</td><td>Dificuldade desde cedo, em uma área específica, apesar de bom ensino.</td></tr><tr><td>O que resolve</td><td>Reforço e retomada das habilidades.</td><td>Acolhimento, tempo e apoio.</td><td>Estratégias adaptadas e avaliação por profissionais.</td></tr><tr><td>Papel do reforço escolar</td><td>Central: o diagnóstico encontra a lacuna e a trilha a recupera.</td><td>Apoio para não perder o conteúdo.</td><td>Complementar: respeita o ritmo, mas não substitui a avaliação.</td></tr></tbody></table></div><h3>Perguntas para diferenciar</h3><ul><li>A dificuldade existe desde os primeiros anos ou começou há pouco?</li><li>Ela aparece em tudo ou em uma área específica?</li><li>O aluno avança quando o conteúdo é retomado desde a base?</li><li>A dificuldade persiste depois de alguns meses de apoio bem feito?</li><li>Há sinais também fora da aprendizagem: atenção, convivência, linguagem, coordenação?</li></ul><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Observar</b><small>registrar o que se vê</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Retomar</b><small>ensinar de novo, desde a base</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Acompanhar</b><small>por seis a oito semanas</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Avaliar a resposta</b><small>avançou ou persiste?</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Encaminhar</b><small>se persiste, conversar com a família</small></div></div><figcaption>Figura. Primeiro o ensino, depois o encaminhamento.</figcaption></figure><div class=\"nota\"><b>Visão e audição primeiro</b><br/>Muitas dificuldades de leitura e de atenção vêm de problemas de visão ou de audição não percebidos. Vale orientar a família a verificar antes de qualquer outra hipótese.</div>"},{"id":"c12","titulo":"O caminho da avaliação e do apoio","html":"<p>A escola não diagnostica. Ela observa, registra, adapta o ensino e orienta a família. O diagnóstico é feito por profissionais de saúde, quase sempre por uma equipe.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quem</th><th>O que faz</th></tr></thead><tbody><tr><td>Professor</td><td>Observa, registra, adapta a aula e informa a coordenação.</td></tr><tr><td>Coordenação pedagógica</td><td>Organiza o estudo de caso, conversa com a família e articula os apoios da escola.</td></tr><tr><td>Atendimento educacional especializado (AEE)</td><td>Identifica barreiras, elabora recursos e apoia o professor. Ocorre em sala de recursos, no contraturno.</td></tr><tr><td>Profissional de apoio escolar</td><td>Auxilia na alimentação, na higiene, na locomoção e na interação, quando há necessidade comprovada.</td></tr><tr><td>Unidade de saúde</td><td>Faz a primeira avaliação e encaminha a especialistas.</td></tr><tr><td>Especialistas</td><td>Neuropediatra, psiquiatra infantil, psicólogo, fonoaudiólogo, terapeuta ocupacional e psicopedagogo avaliam e acompanham.</td></tr><tr><td>CAPS infantojuvenil</td><td>Atende casos de sofrimento psíquico intenso.</td></tr><tr><td>Família</td><td>Busca a avaliação, acompanha o tratamento e informa a escola.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>O apoio não espera o laudo</b><br/>O aluno tem direito a estratégias adaptadas desde que a necessidade é percebida. A orientação do Ministério da Educação é que o atendimento educacional especializado não seja condicionado à apresentação de laudo médico. O laudo ajuda, mas a escola começa a agir antes dele.</div><h3>O que a lei garante</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Norma</th><th>O que garante</th></tr></thead><tbody><tr><td>Lei de Diretrizes e Bases (arts. 58 e 59)</td><td>Currículos, métodos e recursos específicos. Aceleração para alunos com altas habilidades.</td></tr><tr><td>Lei 12.764/2012</td><td>Direitos da pessoa com transtorno do espectro autista. Veda a recusa de matrícula. Prevê acompanhante especializado quando há necessidade comprovada.</td></tr><tr><td>Lei 13.146/2015</td><td>Sistema educacional inclusivo em todos os níveis, com adaptações razoáveis e sem cobrança adicional.</td></tr><tr><td>Lei 13.234/2015</td><td>Identificação, cadastro e atendimento de alunos com altas habilidades.</td></tr><tr><td>Lei 14.254/2021</td><td>Acompanhamento integral de alunos com dislexia, TDAH e outros transtornos de aprendizagem.</td></tr></tbody></table></div>"},{"id":"c13","titulo":"TDAH: estratégias que funcionam em sala","html":"<p>O aluno com TDAH sabe o que deve fazer. A dificuldade está em fazer na hora certa, pelo tempo necessário. Por isso cobrar mais esforço não resolve. O que ajuda é organizar o ambiente, a tarefa e o tempo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dificuldade</th><th>O que o professor vê</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Manter a atenção</td><td>Começa e não termina. Perde-se em instruções longas.</td><td>Uma instrução por vez. Tarefas em partes curtas. Combinar um sinal discreto para retomar o foco.</td></tr><tr><td>Começar</td><td>Demora a iniciar, mesmo sabendo fazer.</td><td>Fazer o primeiro item junto. Dar um tempo curto: \"em dois minutos volto para ver o primeiro\".</td></tr><tr><td>Organizar</td><td>Perde material, esquece tarefas e prazos.</td><td>Rotina no quadro. Lista de passos na carteira. Agenda conferida com a família.</td></tr><tr><td>Ficar parado</td><td>Levanta, mexe em tudo, balança.</td><td>Dar funções com movimento: distribuir material, apagar o quadro. Permitir trabalhar em pé.</td></tr><tr><td>Esperar a vez</td><td>Responde antes da pergunta terminar, interrompe.</td><td>Combinar um gesto para pedir a vez. Dar algo para anotar enquanto espera.</td></tr><tr><td>Controlar o tempo</td><td>Não percebe quanto falta.</td><td>Relógio ou marcador visível. Avisos: \"faltam cinco minutos\".</td></tr><tr><td>Lidar com a frustração</td><td>Desiste ou reage com irritação.</td><td>Tarefas com sucesso rápido. Elogio imediato e específico.</td></tr></tbody></table></div><h3>Onde sentar</h3><ul><li>Perto do professor e do quadro.</li><li>Longe de janelas, da porta e de corredores de passagem.</li><li>Ao lado de um colega organizado e tranquilo.</li><li>Com a carteira limpa: só o material da atividade.</li></ul><h3>Como dar instruções</h3><ol class=\"passos\"><li>Chame o aluno pelo nome e espere o olhar.</li><li>Diga uma instrução curta.</li><li>Peça que ele repita com as próprias palavras.</li><li>Deixe a instrução escrita.</li><li>Volte em poucos minutos para conferir o início.</li></ol><div class=\"nota\"><b>Reconhecer o acerto</b><br/>Alunos com TDAH ouvem muito mais correções do que elogios. Procure o momento em que ele acertou e diga exatamente o que ele fez bem.</div>"},{"id":"c14","titulo":"TDAH: o que é mito e o que se sabe","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Mito</th><th>O que se sabe</th></tr></thead><tbody><tr><td>\"TDAH é falta de limite.\"</td><td>É uma condição do neurodesenvolvimento, com forte componente hereditário. Regras claras ajudam, mas não são a causa nem a cura.</td></tr><tr><td>\"Se ele presta atenção no jogo, não tem TDAH.\"</td><td>A atenção depende do interesse e do retorno imediato. A dificuldade aparece em tarefas longas e pouco estimulantes.</td></tr><tr><td>\"Só menino agitado tem TDAH.\"</td><td>Meninas têm com frequência a forma desatenta: são quietas, distraídas e passam despercebidas.</td></tr><tr><td>\"Isso passa com a idade.\"</td><td>Em muitos casos os sintomas continuam na adolescência e na vida adulta, com outra aparência.</td></tr><tr><td>\"Todo aluno agitado tem TDAH.\"</td><td>Agitação pode vir de sono ruim, ansiedade, fome, aula inadequada ou situação difícil em casa.</td></tr><tr><td>\"Remédio resolve tudo.\"</td><td>O tratamento é decisão do médico e da família. Com ou sem medicação, o aluno precisa de estratégias em sala.</td></tr><tr><td>\"Ele é inteligente, então não precisa de ajuda.\"</td><td>Inteligência e TDAH não se excluem. Muitos alunos capazes rendem abaixo do que sabem.</td></tr></tbody></table></div><h3>A forma desatenta, que quase ninguém vê</h3><ul><li>Parece \"no mundo da lua\".</li><li>É lento para copiar e para terminar.</li><li>Esquece o que acabou de ouvir.</li><li>Comete erros por descuido em tarefas que sabe fazer.</li><li>Evita atividades que pedem esforço mental prolongado.</li><li>Não atrapalha a aula, por isso raramente é notado.</li></ul><div class=\"nota alerta\"><b>O professor não fala em medicação</b><br/>Sugerir, criticar ou cobrar o uso de remédio não cabe à escola. Se a família comentar o assunto, o professor ouve e relata o que observa em sala. A decisão é do médico e da família.</div><div class=\"pratica\"><div class=\"tt\">Para praticar · olhe a sua turma</div><div class=\"q\"><b>1.</b> Há um aluno quieto e distraído que você talvez não tenha notado? O que você observou?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que estratégia deste capítulo você pode testar com ele nesta semana?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c15","titulo":"Autismo: comunicação, rotina e sentidos","html":"<p>O espectro autista reúne pessoas muito diferentes entre si. Algumas falam bastante e têm ótimo desempenho escolar. Outras não usam a fala e precisam de apoio intenso. O que elas têm em comum são diferenças na comunicação social e um padrão de interesses e comportamentos mais restrito e repetitivo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>O que pode acontecer</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Comunicação</td><td>Entende a linguagem ao pé da letra. Não percebe ironia nem duplo sentido.</td><td>Falar de forma direta e concreta. Evitar expressões figuradas ou explicá-las.</td></tr><tr><td>Interação</td><td>Prefere ficar só ou não sabe como entrar na brincadeira.</td><td>Ensinar o que fazer em cada situação. Formar duplas com colegas acolhedores.</td></tr><tr><td>Rotina</td><td>Sofre com mudanças inesperadas.</td><td>Rotina visual do dia. Avisar antes de qualquer mudança.</td></tr><tr><td>Interesses</td><td>Tem um tema de grande interesse e fala muito sobre ele.</td><td>Usar o tema como porta de entrada para os conteúdos.</td></tr><tr><td>Sentidos</td><td>Incomoda-se muito com barulho, luz, cheiros ou toque.</td><td>Lugar mais calmo. Permitir protetor de ouvido. Avisar antes de sinais sonoros.</td></tr><tr><td>Movimentos</td><td>Balança o corpo ou as mãos, repete sons.</td><td>Não reprimir quando não machuca nem atrapalha. Esses movimentos ajudam a se regular.</td></tr><tr><td>Contato visual</td><td>Não olha nos olhos.</td><td>Não exigir. Ele pode ouvir melhor sem olhar.</td></tr></tbody></table></div><h3>Quando o aluno entra em crise</h3><p>A crise é uma sobrecarga, e não birra. O aluno perde o controle porque recebeu mais estímulo do que consegue processar.</p><div class=\"tb\"><table><thead><tr><th>Antes</th><th>Durante</th><th>Depois</th></tr></thead><tbody><tr><td>Conhecer os gatilhos com a família. Notar os sinais: inquietação, tapar os ouvidos, isolar-se. Oferecer uma pausa.</td><td>Manter a calma e a voz baixa. Reduzir barulho e luz. Afastar os outros alunos. Falar pouco. Não segurar, salvo risco de se machucar.</td><td>Dar tempo para se recuperar. Não cobrar explicação. Retomar a rotina. Registrar o que ocorreu antes da crise.</td></tr></tbody></table></div><div class=\"nota\"><b>Um combinado de pausa</b><br/>Combine com o aluno e a família um sinal e um lugar para a pausa: um canto da sala ou outro espaço com um adulto. Usar a pausa antes da crise é sinal de autonomia.</div>"},{"id":"c16","titulo":"Dislexia: ler e escrever com apoio","html":"<p>A dislexia é uma dificuldade específica e persistente em reconhecer palavras e em soletrar. Ela não tem relação com inteligência nem com falta de esforço. O aluno entende quando ouve, mas a leitura custa tanto que sobra pouca energia para compreender.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Leitura de textos</td><td>Dar o texto antes da aula. Letra maior, com espaço entre as linhas. Ler junto ou permitir ouvir o texto.</td></tr><tr><td>Leitura em voz alta</td><td>Não obrigar diante da turma. Combinar antes o trecho, se ele quiser ler.</td></tr><tr><td>Cópia do quadro</td><td>Entregar o conteúdo impresso ou permitir fotografar, para uso pedagógico.</td></tr><tr><td>Escrita</td><td>Valorizar as ideias. Corrigir a ortografia aos poucos, com um tipo de erro por vez.</td></tr><tr><td>Provas</td><td>Ler os enunciados. Dar mais tempo. Permitir resposta oral. Enunciados curtos e diretos.</td></tr><tr><td>Línguas estrangeiras</td><td>Priorizar a compreensão oral e a conversa.</td></tr><tr><td>Matemática</td><td>Ler o problema em voz alta. A dificuldade pode estar no enunciado, e não na conta.</td></tr><tr><td>Organização</td><td>Agenda, cores por matéria e lista de passos.</td></tr></tbody></table></div><h3>Como apresentar um texto</h3><ul class=\"chk\"><li><span></span>Fonte simples, em tamanho maior.</li><li><span></span>Alinhamento à esquerda, sem justificar.</li><li><span></span>Espaço maior entre as linhas.</li><li><span></span>Parágrafos curtos.</li><li><span></span>Sem texto em letras maiúsculas do começo ao fim.</li><li><span></span>Palavras novas explicadas antes da leitura.</li></ul><h3>Outros transtornos de aprendizagem</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Nome</th><th>O que afeta</th><th>Sinais</th><th>O que ajuda</th></tr></thead><tbody><tr><td>Discalculia</td><td>O sentido de número e o cálculo.</td><td>Conta nos dedos por muito tempo. Não memoriza a tabuada. Confunde sinais. Não estima quantidades.</td><td>Material concreto, reta numérica, tabuada à mão, mais tempo, problemas ligados ao cotidiano.</td></tr><tr><td>Disgrafia</td><td>O traçado da letra.</td><td>Letra ilegível, escrita lenta e cansativa, força excessiva no lápis.</td><td>Reduzir a cópia, aceitar letra de forma, permitir digitar, avaliar oralmente.</td></tr><tr><td>Disortografia</td><td>A escrita correta das palavras.</td><td>Muitos erros que persistem após ensino.</td><td>Trabalhar um tipo de erro por vez e não descontar ortografia fora de Língua Portuguesa.</td></tr><tr><td>Transtorno do desenvolvimento da linguagem</td><td>Compreender e formar frases.</td><td>Vocabulário reduzido, frases curtas, dificuldade de contar um fato.</td><td>Frases simples, apoio visual, tempo para responder, encaminhamento à fonoaudiologia.</td></tr></tbody></table></div>"},{"id":"c17","titulo":"Altas habilidades: como reconhecer","html":"<p>O aluno com altas habilidades nem sempre é o que tira as melhores notas. Muitos se entediam, não fazem tarefas que consideram repetitivas e chegam a ser vistos como desinteressados ou indisciplinados.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Característica</th><th>Como aparece</th></tr></thead><tbody><tr><td>Habilidade acima da média</td><td>Aprende rápido, com poucas repetições. Tem vocabulário avançado. Faz relações que os colegas não fazem.</td></tr><tr><td>Criatividade</td><td>Dá respostas inesperadas. Inventa caminhos próprios. Questiona as regras.</td></tr><tr><td>Envolvimento com a tarefa</td><td>Mergulha por horas no que lhe interessa. Vai além do que foi pedido.</td></tr></tbody></table></div><p>Essas três características, juntas, formam o modelo mais usado para identificar altas habilidades. Elas podem aparecer em qualquer área.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>Exemplos</th></tr></thead><tbody><tr><td>Intelectual</td><td>Raciocínio, memória, curiosidade por temas complexos.</td></tr><tr><td>Acadêmica</td><td>Desempenho muito alto em uma ou mais disciplinas.</td></tr><tr><td>Criativa</td><td>Ideias originais, humor, invenções.</td></tr><tr><td>Liderança</td><td>Organiza grupos, convence, media conflitos.</td></tr><tr><td>Artística</td><td>Música, desenho, teatro, dança.</td></tr><tr><td>Psicomotora</td><td>Esportes e habilidades manuais.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Mito</th><th>O que se sabe</th></tr></thead><tbody><tr><td>\"É bom em tudo.\"</td><td>A maioria se destaca em uma ou duas áreas.</td></tr><tr><td>\"Não precisa de ajuda.\"</td><td>Sem desafio, perde o interesse e pode ter baixo rendimento.</td></tr><tr><td>\"Só existe em família rica.\"</td><td>Há alunos com altas habilidades em todos os meios. Nos mais pobres, são menos identificados.</td></tr><tr><td>\"Sempre tira notas altas.\"</td><td>Muitos têm notas medianas porque não veem sentido nas tarefas.</td></tr><tr><td>\"É emocionalmente maduro.\"</td><td>A maturidade emocional costuma ser a da idade, o que causa descompasso.</td></tr></tbody></table></div><div class=\"nota\"><b>Dupla condição</b><br/>Um aluno pode ter altas habilidades e, ao mesmo tempo, TDAH, autismo ou dislexia. Uma condição costuma esconder a outra: ele compensa a dificuldade com a inteligência e parece apenas mediano.</div>"},{"id":"c18","titulo":"Altas habilidades e autodidatas: como ensinar","html":"<p>O aluno que aprende sozinho precisa de três coisas: não repetir o que já sabe, ter desafio de verdade e continuar convivendo com a turma.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Estratégia</th><th>Como funciona</th><th>Exemplo</th></tr></thead><tbody><tr><td>Compactação</td><td>O aluno mostra que já domina o conteúdo e fica dispensado da prática repetida.</td><td>Acerta os cinco problemas mais difíceis e passa ao desafio.</td></tr><tr><td>Enriquecimento</td><td>Aprofunda o mesmo tema, com mais complexidade.</td><td>Enquanto a turma calcula áreas, ele projeta a planta de uma casa.</td></tr><tr><td>Projeto de investigação</td><td>Pesquisa uma pergunta própria e apresenta o resultado.</td><td>Estuda por que o rio do bairro enche e propõe soluções.</td></tr><tr><td>Monitoria</td><td>Ensina colegas, por tempo limitado.</td><td>Explica um exercício a uma dupla. Não vira ajudante permanente.</td></tr><tr><td>Contrato de estudo</td><td>Combina com o professor metas, prazos e como será avaliado.</td><td>Lista de tarefas obrigatórias e de escolha para o mês.</td></tr><tr><td>Agrupamento</td><td>Trabalha parte do tempo com colegas de interesse semelhante.</td><td>Clube de matemática, de leitura ou de ciências.</td></tr><tr><td>Aceleração</td><td>Avança de ano ou cursa uma disciplina em ano mais adiantado.</td><td>Decisão da escola com a família, prevista na Lei de Diretrizes e Bases.</td></tr></tbody></table></div><h3>O reforço escolar para quem já sabe</h3><ul><li>O diagnóstico mostra o que o aluno já domina, e ele não precisa repetir.</li><li>A trilha avança no ritmo dele.</li><li>Ele pode estudar conteúdos de qualquer matéria do ano.</li><li>O tutor responde às perguntas e propõe que ele explique o raciocínio.</li><li>O mapa da turma mostra ao professor quem está pronto para desafios.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Evite</th></tr></thead><tbody><tr><td>Perguntar o que ele quer aprender.</td><td>Dar mais exercícios do mesmo tipo.</td></tr><tr><td>Aceitar caminhos diferentes para a mesma resposta.</td><td>Exigir o método ensinado quando o dele está correto.</td></tr><tr><td>Ensinar a lidar com o erro e com a frustração.</td><td>Elogiar apenas por ser inteligente.</td></tr><tr><td>Cuidar da convivência com a turma.</td><td>Usá-lo sempre como ajudante.</td></tr><tr><td>Encaminhar para identificação e cadastro.</td><td>Tratar como exibido ou indisciplinado.</td></tr></tbody></table></div><div class=\"nota\"><b>Elogie o esforço</b><br/>Quem ouve sempre que é inteligente passa a evitar desafios para não errar. Elogiar o esforço e a estratégia ensina a persistir.</div>"},{"id":"c19","titulo":"Ensinar de várias formas para todos","html":"<p>Preparar uma aula e depois adaptar para cada aluno é trabalhoso. O desenho universal para a aprendizagem propõe o contrário: planejar desde o início uma aula com várias formas de entrada, de modo que mais alunos consigam participar sem adaptação individual.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Pergunta para o planejamento</th><th>Exemplos</th></tr></thead><tbody><tr><td>Várias formas de apresentar</td><td>O conteúdo chega por mais de um caminho?</td><td>Explicação oral, texto, imagem, vídeo, material concreto, exemplo resolvido.</td></tr><tr><td>Várias formas de fazer e mostrar</td><td>O aluno pode mostrar o que aprendeu de mais de um jeito?</td><td>Escrever, falar, desenhar, montar, gravar, resolver no quadro.</td></tr><tr><td>Várias formas de se envolver</td><td>Há escolha, sentido e desafio na medida certa?</td><td>Temas ligados à vida da turma, opção entre duas atividades, trabalho em dupla, metas curtas.</td></tr></tbody></table></div><h3>Pequenas mudanças que servem a todos</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Mudança</th><th>Quem se beneficia</th></tr></thead><tbody><tr><td>Rotina do dia escrita no quadro</td><td>Alunos autistas, com TDAH, ansiosos e toda a turma.</td></tr><tr><td>Instrução falada e escrita</td><td>Alunos com dislexia, com TDAH, com dificuldade de audição.</td></tr><tr><td>Tarefas em partes, com conferência a cada parte</td><td>Alunos com TDAH, com defasagem e os que se perdem em tarefas longas.</td></tr><tr><td>Tempo extra para quem precisa</td><td>Alunos com dislexia, com disgrafia, ansiosos.</td></tr><tr><td>Escolha entre duas formas de apresentar o trabalho</td><td>Alunos com altas habilidades, com dificuldade de escrita, tímidos.</td></tr><tr><td>Cantinho de pausa na sala</td><td>Alunos autistas, agitados ou em dia difícil.</td></tr><tr><td>Atividades de desafio sempre disponíveis</td><td>Quem termina cedo.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · uma aula, três entradas</div><div class=\"q\"><b>1.</b> Escolha uma aula da próxima semana. De que duas formas você pode apresentar o conteúdo?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> De que duas formas os alunos poderão mostrar o que aprenderam?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c20","titulo":"Avaliar sem prejudicar","html":"<p>Avaliar com justiça não é dar a mesma prova a todos nas mesmas condições. É verificar se cada aluno aprendeu, retirando o que impede de mostrar. Adaptar a forma não reduz a exigência.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Necessidade</th><th>Adaptações possíveis</th></tr></thead><tbody><tr><td>Dificuldade de leitura</td><td>Leitura dos enunciados, prova oral, letra maior, menos texto por página.</td></tr><tr><td>Dificuldade de escrita</td><td>Respostas orais, digitação, questões de marcar, não descontar a letra.</td></tr><tr><td>Dificuldade de atenção</td><td>Prova em partes, ambiente com menos estímulo, pausas, uma questão por página.</td></tr><tr><td>Ansiedade intensa</td><td>Mais tempo, local reservado, avaliação por trabalhos e observação.</td></tr><tr><td>Autismo</td><td>Enunciados diretos, sem duplo sentido. Aviso prévio da data e do formato.</td></tr><tr><td>Discalculia</td><td>Uso de tabuada e de material de apoio. Avaliar o raciocínio, além do resultado.</td></tr><tr><td>Altas habilidades</td><td>Questões de aprofundamento e possibilidade de projeto no lugar de parte das provas.</td></tr></tbody></table></div><h3>O que não muda</h3><ul><li>O objetivo de aprendizagem.</li><li>O respeito às regras combinadas.</li><li>O registro do que foi adaptado, para que os outros professores saibam.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Dúvida comum</th><th>Resposta</th></tr></thead><tbody><tr><td>\"Não é injusto com os outros?\"</td><td>Injusto é avaliar a leitura quando se quer saber se o aluno entende ciências.</td></tr><tr><td>\"E se os colegas reclamarem?\"</td><td>Explique que cada um recebe o que precisa para aprender, como óculos para quem não enxerga bem.</td></tr><tr><td>\"Preciso de laudo para adaptar?\"</td><td>Não. A adaptação responde à necessidade observada.</td></tr><tr><td>\"Posso dar uma prova mais fácil?\"</td><td>Mudar o objetivo é uma decisão maior, tomada com a coordenação e registrada no plano individual.</td></tr></tbody></table></div>"},{"id":"c21","titulo":"O plano individual do aluno","html":"<p>O plano individual reúne, em uma ou duas páginas, o que a escola sabe sobre o aluno e o que combinou fazer. Ele evita que cada professor recomece do zero e garante continuidade de um ano para o outro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte</th><th>O que registra</th></tr></thead><tbody><tr><td>Quem é o aluno</td><td>Interesses, pontos fortes e o que o acalma.</td></tr><tr><td>O que já sabe</td><td>Em cada área, com base nas atividades e no diagnóstico do reforço.</td></tr><tr><td>Barreiras</td><td>O que dificulta a participação e a aprendizagem.</td></tr><tr><td>Objetivos</td><td>Poucos, claros e possíveis de verificar em um bimestre.</td></tr><tr><td>Estratégias</td><td>O que todos os professores farão em sala.</td></tr><tr><td>Avaliação</td><td>Como será avaliado e que adaptações terá.</td></tr><tr><td>Apoios</td><td>AEE, profissional de apoio, atendimentos de saúde.</td></tr><tr><td>Família</td><td>O que foi combinado e como será o contato.</td></tr><tr><td>Revisão</td><td>Data para avaliar e ajustar.</td></tr></tbody></table></div><div class=\"rapido\"><p><b>Aluno (iniciais), ano e turma:</b> ____________________ <b>Período:</b> ____________________</p><p><b>Pontos fortes e interesses:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que dificulta:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Objetivos do bimestre (até três):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Estratégias de todos os professores:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Adaptações na avaliação:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Data de revisão:</b> ____/____/______ <b>Participaram:</b> ____________________</p></div><div class=\"nota\"><b>Feito com o aluno</b><br/>Sempre que possível, pergunte ao próprio aluno o que o ajuda e o que o atrapalha. Ele costuma saber.</div><div class=\"nota alerta\"><b>Documento reservado</b><br/>O plano contém dados pessoais sensíveis. Fica com a coordenação e é compartilhado apenas com os professores do aluno e com a família.</div>"},{"id":"c22","titulo":"A turma como parte da solução","html":"<p>O modo como os colegas tratam o aluno pesa tanto quanto as estratégias do professor. Alunos neurodivergentes estão entre os que mais sofrem bullying.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que o professor pode fazer</th></tr></thead><tbody><tr><td>Colegas perguntam por que ele tem tratamento diferente</td><td>Explicar que cada pessoa aprende de um jeito e recebe o que precisa. Não revelar diagnóstico.</td></tr><tr><td>O aluno fica só no recreio</td><td>Propor jogos com regras claras. Combinar com dois colegas que o convidem.</td></tr><tr><td>A turma ri de um comportamento</td><td>Interromper na hora, sem expor. Retomar depois com a turma os combinados de respeito.</td></tr><tr><td>Ninguém quer formar grupo com ele</td><td>Formar os grupos você mesmo. Dar a cada um uma função.</td></tr><tr><td>O aluno reage com agressividade</td><td>Entender o que veio antes. Muitas reações respondem a provocações que o adulto não viu.</td></tr></tbody></table></div><h3>Falar de diferenças com a turma</h3><ul><li>Trate do tema em geral, com livros, filmes e rodas de conversa, sem apontar ninguém.</li><li>Mostre que todos têm facilidades e dificuldades.</li><li>Valorize em público o que o aluno faz bem.</li><li>Só fale do diagnóstico de um aluno se ele e a família quiserem, e do jeito que quiserem.</li></ul><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · quando um colega pergunta</div><div class=\"f\"><div class=\"q\">Aluno</div><div class=\"b\">Professora, por que o Davi pode usar fone na aula?</div></div><div class=\"f o\"><div class=\"q\">Professora</div><div class=\"b\">Porque o barulho incomoda o Davi muito mais do que incomoda você. O fone ajuda a aprender, como os óculos ajudam a Ana a enxergar.</div></div><div class=\"f\"><div class=\"q\">Aluno</div><div class=\"b\">Eu também quero.</div></div><div class=\"f o\"><div class=\"q\">Professora</div><div class=\"b\">Se alguma coisa atrapalhar você a aprender, me conta. A gente procura o que ajuda você.</div></div></div>"},{"id":"c23","titulo":"Conversas delicadas com os responsáveis","html":"<p>Algumas famílias recebem a observação da escola com alívio. Outras reagem com medo, negação ou raiva. Todas precisam de tempo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Reação da família</th><th>O que pode estar por trás</th><th>Como conduzir</th></tr></thead><tbody><tr><td>\"Meu filho não tem nada.\"</td><td>Medo do rótulo ou de ser culpada.</td><td>Não insistir no nome. Descrever o que se vê e propor: \"Vamos observar juntos por um mês?\"</td></tr><tr><td>\"Em casa ele não é assim.\"</td><td>É verdade: em casa as exigências são outras.</td><td>Explicar a diferença entre os ambientes e mostrar exemplos de atividades.</td></tr><tr><td>\"A escola é que não sabe ensinar.\"</td><td>Experiências ruins anteriores.</td><td>Ouvir, mostrar o que a escola já está fazendo e pedir sugestões do que funciona em casa.</td></tr><tr><td>\"Então ele tem TDAH?\"</td><td>Ansiedade por uma resposta.</td><td>Dizer que a escola não diagnostica e orientar o caminho da avaliação.</td></tr><tr><td>\"Quero um professor só para ele.\"</td><td>Medo de que o filho fique sem atenção.</td><td>Explicar os apoios existentes e como são definidos. Registrar o pedido e levar à direção.</td></tr><tr><td>Família que não comparece</td><td>Horário de trabalho, vergonha, cansaço.</td><td>Oferecer outro horário, telefonema ou visita com apoio da direção.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · a primeira conversa</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Obrigado por vir. Queria falar do Lucas, de quem gosto muito. Ele é curioso e tem ótimas ideias nas discussões.</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Ele aprontou alguma coisa?</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Não. Tenho notado que ele demora a começar as atividades e raramente termina. Trouxe alguns cadernos para a senhora ver.</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Em casa também é uma luta para fazer a lição.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Isso me ajuda a entender. Na sala, mudei o lugar dele e divido as tarefas em partes. Melhorou um pouco. Acho que vale conversar com o médico da unidade de saúde. Posso escrever o que observo, para a senhora levar.</div></div></div><h3>Relatório para a família levar ao serviço de saúde</h3><ul><li>Descreve fatos observados, com frequência e exemplos.</li><li>Diz o que a escola já tentou e com que resultado.</li><li>Aponta os pontos fortes do aluno.</li><li>Não traz hipótese de diagnóstico.</li><li>É assinado pelo professor e pela coordenação.</li></ul>"},{"id":"c24","titulo":"Casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a aluna que ninguém notava</div><p><b>Situação.</b> No 5º ano, uma aluna quieta copia devagar, esquece o material e erra por descuido. Nunca atrapalha a aula.</p><p><b>O que fazer.</b></p><ol><li>Registre por duas semanas o que observa.</li><li>Coloque-a perto do quadro e divida as tarefas em partes.</li><li>Confira o início de cada atividade.</li><li>Converse com a família sobre o que nota em casa.</li><li>Leve o caso à coordenação.</li></ol><p><b>Resultado esperado.</b> A aluna passa a terminar as atividades, e a família é orientada a buscar avaliação.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o aluno que terminava em cinco minutos</div><p><b>Situação.</b> No 7º ano, um aluno acaba os exercícios muito antes dos colegas e passa a conversar e a provocar.</p><p><b>O que fazer.</b></p><ol><li>Verifique no mapa da turma o que ele já domina.</li><li>Dispense-o da prática repetida quando ele mostrar domínio.</li><li>Combine um projeto de investigação com tema de interesse dele.</li><li>Dê a ele a função de explicar um exercício a uma dupla, uma vez por semana.</li><li>Informe a coordenação para a identificação de altas habilidades.</li></ol><p><b>Resultado esperado.</b> O aluno se envolve com o projeto, e as provocações diminuem.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a mudança de sala</div><p><b>Situação.</b> Um aluno autista do 4º ano entra em crise quando a turma é levada à quadra sem aviso.</p><p><b>O que fazer.</b></p><ol><li>Leve o aluno a um lugar calmo, com pouca fala.</li><li>Depois, registre o que ocorreu antes da crise.</li><li>Passe a escrever a rotina do dia no quadro.</li><li>Avise com antecedência qualquer mudança.</li><li>Combine com ele um sinal para pedir pausa.</li></ol><p><b>Resultado esperado.</b> As crises ficam raras, e o aluno passa a pedir a pausa antes de se desorganizar.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a leitura em voz alta</div><p><b>Situação.</b> Uma aluna do 6º ano falta sempre no dia da leitura em voz alta. Lê devagar e troca letras.</p><p><b>O que fazer.</b></p><ol><li>Não a exponha à leitura diante da turma.</li><li>Entregue o texto com antecedência.</li><li>Avalie a compreensão por perguntas orais.</li><li>Converse com a família e oriente a avaliação, começando por visão e audição.</li><li>Registre as adaptações para os outros professores.</li></ol><p><b>Resultado esperado.</b> A aluna volta a frequentar as aulas e participa das discussões sobre os textos.</p></div>"},{"id":"c25","titulo":"Erros comuns e como evitá-los","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Erro</th><th>Por que é um problema</th><th>O que fazer</th></tr></thead><tbody><tr><td>Dar um diagnóstico</td><td>Não cabe ao professor e assusta a família.</td><td>Descrever o que observa.</td></tr><tr><td>Esperar o laudo para agir</td><td>O aluno perde meses de aprendizagem.</td><td>Adaptar desde que a necessidade é percebida.</td></tr><tr><td>Reduzir a exigência em vez de adaptar</td><td>O aluno aprende menos do que poderia.</td><td>Mudar o caminho, manter o objetivo.</td></tr><tr><td>Tratar todos os alunos com o mesmo diagnóstico do mesmo jeito</td><td>Cada aluno é diferente.</td><td>Observar o que funciona com cada um.</td></tr><tr><td>Deixar o aluno só com o profissional de apoio</td><td>Ele fica isolado dentro da própria sala.</td><td>O professor é o responsável pelo ensino de todos.</td></tr><tr><td>Expor o aluno diante da turma</td><td>Gera vergonha e bullying.</td><td>Combinar apoios de forma discreta.</td></tr><tr><td>Punir o que o aluno não controla</td><td>Aumenta a ansiedade e piora o comportamento.</td><td>Ensinar a habilidade que falta.</td></tr><tr><td>Esquecer quem aprende rápido</td><td>O aluno se entedia e desiste.</td><td>Oferecer desafio de verdade.</td></tr><tr><td>Comparar com irmãos e colegas</td><td>Reforça a ideia de incapacidade.</td><td>Comparar o aluno com ele mesmo.</td></tr><tr><td>Agir sozinho</td><td>O professor se desgasta e o aluno não tem continuidade.</td><td>Trabalhar com a coordenação, o AEE e a família.</td></tr></tbody></table></div><h3>O que levar deste guia</h3><ul class=\"chk\"><li><span></span>Observo e registro fatos, sem dar nome ao que vejo.</li><li><span></span>Começo a adaptar a aula antes de qualquer laudo.</li><li><span></span>Uso rotina visível e instruções curtas com toda a turma.</li><li><span></span>Ofereço mais de uma forma de aprender e de mostrar o que se aprendeu.</li><li><span></span>Tenho desafios prontos para quem termina cedo.</li><li><span></span>Converso com a família partindo dos pontos fortes do aluno.</li><li><span></span>Levo à coordenação o que observo.</li><li><span></span>Guardo sigilo sobre diagnósticos e relatórios.</li></ul>"},{"id":"c26","titulo":"Alunos com deficiência: primeiros cuidados em sala","html":"<p>Além dos transtornos tratados neste guia, a sala de aula recebe alunos com deficiência visual, auditiva, física, intelectual e múltipla. O atendimento educacional especializado orienta cada caso. O quadro abaixo reúne cuidados que todo professor pode adotar desde o primeiro dia.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Deficiência</th><th>Cuidados na aula</th><th>Na comunicação com o aluno</th></tr></thead><tbody><tr><td>Visual (cegueira e baixa visão)</td><td>Lugar perto do quadro e com boa luz. Letra ampliada e contraste. Descrever em voz alta o que se escreve e as imagens. Material em relevo ou em braile, com apoio do atendimento especializado. Manter os móveis no mesmo lugar.</td><td>Identificar-se ao chegar. Avisar ao sair. Perguntar se quer ajuda antes de ajudar.</td></tr><tr><td>Auditiva (surdez e perda parcial)</td><td>Lugar de frente para o professor. Falar de frente, sem cobrir a boca. Apoio visual: escrita, imagens, esquemas. Intérprete de Libras quando o aluno a utiliza.</td><td>Chamar a atenção com um toque leve ou um aceno. Falar com o aluno, e não com o intérprete.</td></tr><tr><td>Física</td><td>Sala e banheiro acessíveis. Carteira adequada. Mais tempo para escrever ou alternativas à escrita. Participação nas aulas de educação física com adaptações.</td><td>Conversar na altura do aluno. Não mover a cadeira de rodas sem pedir.</td></tr><tr><td>Intelectual</td><td>Instruções curtas, uma por vez. Material concreto. Mais repetição e mais tempo. Objetivos definidos no plano individual. Atividades com o mesmo tema da turma.</td><td>Linguagem simples, sem infantilizar. Dar tempo para responder.</td></tr><tr><td>Múltipla e surdocegueira</td><td>Plano individual detalhado, com a família e o atendimento especializado.</td><td>Usar a forma de comunicação que o aluno utiliza.</td></tr></tbody></table></div><h3>Vale para todos</h3><ul><li>Pergunte ao aluno e à família o que funciona.</li><li>Presuma capacidade. Comece pelo que o aluno consegue.</li><li>Garanta que ele participe das mesmas atividades que a turma, com as adaptações necessárias.</li><li>Combine com a turma formas naturais de ajudar, sem fazer pelo colega.</li><li>Trabalhe junto com o atendimento educacional especializado e com o profissional de apoio.</li><li>Registre as adaptações que deram certo, para os outros professores.</li></ul><h3>No reforço escolar</h3><ul><li>Os recursos de acessibilidade do próprio aparelho, como ampliação e leitura de tela, ajudam alunos com deficiência visual.</li><li>Um adulto pode ler os enunciados ou ajudar no manuseio. A resposta continua sendo do aluno.</li><li>Sessões mais curtas e mais frequentes funcionam melhor para alunos que se cansam rápido.</li><li>As dificuldades de uso são comunicadas à direção, para que a rede busque soluções.</li></ul><div class=\"nota\"><b>A deficiência não define o que o aluno pode aprender</b><br/>O que limita a aprendizagem, na maioria das vezes, são as barreiras: o material que ele não consegue ler, a instrução que não entende, a atividade de que é dispensado.</div>"},{"id":"c27","titulo":"Perguntas frequentes","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td>Posso dizer à família que suspeito de TDAH ou de autismo?</td><td>Não. Descreva o que observa e oriente a procurar a unidade de saúde.</td></tr><tr><td>A família não aceita buscar avaliação. E agora?</td><td>Continue adaptando a aula, mantenha o diálogo e registre. Se houver prejuízo grave ao aluno, a direção avalia acionar a rede.</td></tr><tr><td>O aluno tem laudo, mas eu não recebi orientação.</td><td>Procure a coordenação e o atendimento educacional especializado. Pergunte à família o que funciona.</td></tr><tr><td>Tenho trinta alunos. Como adaptar para um?</td><td>Comece pelo que serve a todos: rotina visível, instruções curtas, tarefas em partes. Depois, uma ou duas adaptações individuais.</td></tr><tr><td>Adaptar não é facilitar?</td><td>Não. Muda-se o caminho para chegar ao mesmo objetivo.</td></tr><tr><td>Posso reprovar um aluno com deficiência?</td><td>A decisão segue as normas da rede e o plano individual, e é tomada pelo conselho de classe, com a coordenação.</td></tr><tr><td>O aluno precisa de um profissional de apoio. Quem decide?</td><td>A necessidade é avaliada pela escola e pela Secretaria, com a família, conforme as normas da rede.</td></tr><tr><td>O profissional de apoio pode dar a aula para o aluno?</td><td>Não. O ensino é responsabilidade do professor. O apoio ajuda na participação.</td></tr><tr><td>O aluno autista não olha para mim. Está prestando atenção?</td><td>Pode estar. Verifique pelo que ele faz e responde.</td></tr><tr><td>Devo contar à turma o diagnóstico do colega?</td><td>Só se ele e a família quiserem, e do jeito que quiserem.</td></tr><tr><td>O aluno com altas habilidades atrapalha a aula. O que faço?</td><td>Verifique se há desafio suficiente. O tédio costuma estar por trás.</td></tr><tr><td>Posso avançar de ano um aluno com altas habilidades?</td><td>A aceleração é prevista em lei e decidida pela escola, com a família e conforme as normas da rede.</td></tr><tr><td>O reforço escolar serve para esses alunos?</td><td>Sim, porque respeita o ritmo de cada um. Alguns precisam de apoio na leitura ou no manuseio.</td></tr><tr><td>Onde encontro ajuda?</td><td>Na coordenação, no atendimento educacional especializado e na equipe da Secretaria.</td></tr></tbody></table></div>"},{"id":"c28","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"Sinais do espectro autista\"</td><td>O que cabe a nós e o que não cabe? Que sinais já observamos?</td></tr><tr><td>2</td><td>De \"Dislexia\" até \"Uma sala que funciona para todos\"</td><td>Como registramos o que observamos? Como conversamos com as famílias?</td></tr><tr><td>3</td><td>De \"Palavras que ajudam\" até \"TDAH: o que é mito\"</td><td>Que palavras usamos sem perceber? Como diferenciamos defasagem de transtorno?</td></tr><tr><td>4</td><td>De \"Autismo\" até \"Altas habilidades: como ensinar\"</td><td>Que estratégias já usamos? Quem são os nossos alunos que aprendem rápido?</td></tr><tr><td>5</td><td>De \"Ensinar de várias formas\" até o final</td><td>Que mudança serve a todos? Como avaliamos? Temos planos individuais?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c29","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Diante de sinais de TDAH, o professor deve:</p><ol type=\"a\"><li>Trocar o aluno de turma.</li><li>Informar o diagnóstico à família.</li><li>Observar, registrar, adaptar e comunicar à coordenação.</li><li>Esperar o laudo para agir.</li></ol></div><div class=\"qz\"><p><b>2.</b> As adaptações em sala:</p><ol type=\"a\"><li>São proibidas sem autorização.</li><li>Dependem de acompanhante.</li><li>Só podem começar com laudo.</li><li>Podem começar assim que a necessidade é percebida.</li></ol></div><div class=\"qz\"><p><b>3.</b> Um aluno termina tudo rápido e fica entediado. Uma boa resposta é:</p><ol type=\"a\"><li>Oferecer desafios mais complexos.</li><li>Repreender.</li><li>Deixá-lo sem atividade.</li><li>Dar mais exercícios iguais.</li></ol></div><div class=\"qz\"><p><b>4.</b> Um bom registro de observação:</p><ol type=\"a\"><li>Traz a opinião do professor.</li><li>Descreve fatos, frequência e contexto.</li><li>Traz o diagnóstico provável.</li><li>Compara o aluno com os colegas.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> c) Observar, registrar, adaptar e comunicar à coordenação. O diagnóstico cabe à saúde.</p><p><b>2.</b> d) Podem começar assim que a necessidade é percebida. O apoio não depende de laudo.</p><p><b>3.</b> a) Oferecer desafios mais complexos. Mais do mesmo aumenta o tédio.</p><p><b>4.</b> b) Descreve fatos, frequência e contexto. Fatos ajudam a família e a saúde.</p></div>"},{"id":"c30","titulo":"Glossário","html":"<dl><dt>Adaptação razoável</dt><dd>Ajuste necessário para que o aluno participe em igualdade com os demais.</dd><dt>Altas habilidades ou superdotação</dt><dd>Potencial elevado em uma ou mais áreas, com criatividade e envolvimento com a tarefa.</dd><dt>Atendimento educacional especializado</dt><dd>Serviço que identifica barreiras e oferece recursos e apoio, em geral no contraturno.</dd><dt>Autismo</dt><dd>Condição do neurodesenvolvimento com diferenças na comunicação social e padrões restritos de interesses e comportamentos.</dd><dt>Barreira</dt><dd>O que impede ou dificulta a participação do aluno.</dd><dt>Defasagem</dt><dd>Diferença entre o que o aluno sabe e o que se espera para o ano, por conteúdos não aprendidos.</dd><dt>Desenho universal para a aprendizagem</dt><dd>Planejamento da aula com várias formas de apresentar, de fazer e de se envolver.</dd><dt>Discalculia</dt><dd>Dificuldade específica e persistente com números e cálculo.</dd><dt>Dislexia</dt><dd>Dificuldade específica e persistente em reconhecer palavras e soletrar.</dd><dt>Dupla condição</dt><dd>Presença de altas habilidades junto com um transtorno ou uma deficiência.</dd><dt>Laudo</dt><dd>Documento de profissional de saúde com avaliação e diagnóstico.</dd><dt>Neurodivergente</dt><dd>Pessoa cujo desenvolvimento neurológico difere do mais comum.</dd><dt>Plano individual</dt><dd>Documento com objetivos, estratégias e adaptações combinados para um aluno.</dd><dt>Profissional de apoio escolar</dt><dd>Pessoa que auxilia o aluno em alimentação, higiene, locomoção e interação.</dd><dt>TDAH</dt><dd>Transtorno do déficit de atenção e hiperatividade.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"Um aluno do 6º ano erra operações que dependem do 4º ano, mas avança quando o conteúdo é retomado. Isso indica:","alternativas":["Falta de interesse.","Um transtorno.","Uma defasagem.","Altas habilidades."],"correta":2,"explicacao":"A defasagem se recupera com retomada desde a base."},{"pergunta":"Para adaptar a aula a um aluno, o professor:","alternativas":["Deve esperar o próximo ano.","Precisa do laudo.","Pode começar assim que percebe a necessidade.","Precisa de autorização do médico."],"correta":2,"explicacao":"O apoio não é condicionado ao laudo."},{"pergunta":"A forma desatenta do TDAH costuma:","alternativas":["Passar despercebida.","Aparecer só em meninos.","Desaparecer com bronca.","Atrapalhar muito a aula."],"correta":0,"explicacao":"São alunos quietos e distraídos."},{"pergunta":"Diante de uma crise de um aluno autista, o professor deve:","alternativas":["Segurá-lo com força.","Exigir explicação na hora.","Falar alto para ele ouvir.","Reduzir os estímulos e manter a calma."],"correta":3,"explicacao":"A crise é uma sobrecarga."},{"pergunta":"Para um aluno com dislexia, é adequado:","alternativas":["Ler os enunciados e dar mais tempo.","Descontar todos os erros de ortografia.","Reduzir o conteúdo.","Obrigar a ler em voz alta."],"correta":0,"explicacao":"Muda-se a forma, mantém-se o objetivo."},{"pergunta":"O aluno com altas habilidades precisa de:","alternativas":["Mais exercícios do mesmo tipo.","Desafio e aprofundamento.","Nenhum apoio.","Ser o ajudante permanente da turma."],"correta":1,"explicacao":"Sem desafio, perde o interesse."},{"pergunta":"Sobre medicação, o professor:","alternativas":["Recomenda à família.","Não opina. Relata o que observa em sala.","Cobra o uso.","Critica o uso."],"correta":1,"explicacao":"A decisão é do médico e da família."},{"pergunta":"O plano individual do aluno é:","alternativas":["Um documento só da saúde.","Opcional e verbal.","Público, afixado na sala.","Reservado e compartilhado com os professores do aluno e a família."],"correta":3,"explicacao":"Contém dados pessoais sensíveis."}];
